// Mirrors the old mutable chalk.level switch: the CliPrinter constructor
// flips this module-wide so helpers like getBarText stay free functions.
let colorEnabled = true;

function style(styles, text) {
    if (!colorEnabled) return text;
    // enableColor is explicit, so skip TTY detection like chalk.level = 3 did
    return styleText(styles, text, { validateStream: false });
}

function getBarText(percent, maxBarSize) {
    maxBarSize = Math.max(0, maxBarSize);
    const barNumber = Math.max(Math.ceil((percent / 100) * maxBarSize), 1);
    return (
        style('blue', new Array(barNumber + 1).join(figure.square)) +
        style(
            ['blue', 'dim'],
            new Array(Math.max(0, maxBarSize - barNumber + 1)).join(
                figure.square
            )
        )
    );
}

